/bin/zsh -lc "cat > tb_check.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 1;
  reg write_en = 0;
  reg [7:0] write_addr = 0;
  reg [3:0] write_data = 0;
  reg read_en = 0;
  reg [7:0] read_addr = 0;
  wire [3:0] read_data;

  TopModule dut(
    .clk(clk), .rst_n(rst_n), .write_en(write_en), .write_addr(write_addr), .write_data(write_data),
    .read_en(read_en), .read_addr(read_addr), .read_data(read_data)
  );

  always #5 clk = ~clk;

  task expect;
    input [3:0] actual;
    input [3:0] expected;
    input [255:0] msg;
    begin
      if (actual "'!== expected) begin
        $display("FAIL: %0s actual=%b expected=%b", msg, actual, expected);
        $finish(1);
      end
    end
  endtask

  initial begin
    rst_n = 0;
    #1;
    expect(dut.myRAM[0], 4'"'b0000, \"reset mem0\");
    expect(dut.myRAM[7], 4'b0000, \"reset mem7\");
    expect(read_data, 4'b0000, \"reset read_data\");

    #9 rst_n = 1;

    @(posedge clk);
    write_en <= 1;
    write_addr <= 8'd3;
    write_data <= 4'hA;

    @(posedge clk);
    write_en <= 0;
    read_en <= 1;
    read_addr <= 8'd3;

    @(posedge clk);
    #1 expect(read_data, 4'hA, \"read back addr3\");

    read_addr <= 8'd11;
    @(posedge clk);
    #1 expect(read_data, 4'hA, \"address wraps to low 3 bits\");

    "'$display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -Wall -o simv_check TopModule.sv tb_check.sv && vvp simv_check'

